const flags = new Map();

export function enable(name) {
  flags.set(name, true);
}

export function disable(name) {
  flags.delete(name);
}

export function isEnabled(name) {
  return flags.get(name) === true;
}

export function enabledCount() {
  return flags.size;
}

export function resetFlags() {
  flags.clear();
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { enable, disable, isEnabled, enabledCount } from '../src/flags.js';

test('enable turns a flag on', () => {
  enable('beta-banner');
  assert.equal(isEnabled('beta-banner'), true);
});

test('disable turns a flag off again', () => {
  enable('holiday-theme');
  disable('holiday-theme');
  assert.equal(isEnabled('holiday-theme'), false);
});

test('unknown flags read as disabled', () => {
  assert.equal(isEnabled('dark-mode'), false);
});

test('a fresh session starts with no flags enabled', () => {
  assert.equal(enabledCount(), 0);
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { enable, isEnabled, resetFlags, enabledCount } from '../src/flags.js';

const root = process.cwd();
const ORACLE_FILE = 'verify-deflake.mjs';

// 1) The flags module still means what it meant.
resetFlags();
enable('oracle-probe');
assert.equal(isEnabled('oracle-probe'), true, 'enable must still work');
assert.equal(enabledCount(), 1, 'enabledCount must still count');
resetFlags();
assert.equal(enabledCount(), 0, 'resetFlags must still clear');
console.log('DEFLAKE_ORACLE flags semantics ok');

function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}

function copyTree(dest) {
  rmSync(dest, { recursive: true, force: true });
  mkdirSync(dest, { recursive: true });
  cpSync(join(root, 'src'), join(dest, 'src'), { recursive: true });
  cpSync(join(root, 'tests'), join(dest, 'tests'), { recursive: true });
  rmSync(join(dest, 'tests', ORACLE_FILE), { force: true });
  cpSync(join(root, 'package.json'), join(dest, 'package.json'));
  return dest;
}

// 2) Five consecutive green runs of the real suite.
for (let run = 1; run <= 5; run += 1) {
  assert.equal(runSuite(root), 0, `full-suite run ${run} of 5 must be green`);
}
console.log('DEFLAKE_ORACLE stable 5x');

// 3) The pristine-session assertion survives, unweakened and unskipped.
const testFiles = readdirSync(join(root, 'tests')).filter(
  (name) => name !== ORACLE_FILE && /\.(mjs|cjs|js)$/.test(name),
);
const combined = testFiles
  .map((name) => readFileSync(join(root, 'tests', name), 'utf8'))
  .join('\n');
assert.match(
  combined,
  /enabledCount\s*\(\s*\)\s*(?:,\s*0|===\s*0)/,
  'the pristine-session assertion (enabledCount() must be 0) has to survive',
);
assert.ok(
  !/\.skip\s*\(|\.todo\s*\(|\.only\s*\(|\{\s*skip\s*:|\{\s*todo\s*:/.test(combined),
  'no test may be skipped, stubbed as todo, or narrowed with only',
);
console.log('DEFLAKE_ORACLE assertion intact');

// 4) Order robustness: tests appended at the END of the suite must inherit
// the cleanup. The first probe enables a flag and never cleans up; the
// second expects a pristine session anyway. Only hygiene that covers every
// test (beforeEach/afterEach-style) passes both - a one-off reset inside
// the seeded failing test, or a reorder, fails here. Aliased imports keep
// the probe valid whatever the model did to the file's own imports.
const hostFile = testFiles.find((name) =>
  /enabledCount/.test(readFileSync(join(root, 'tests', name), 'utf8')),
);
assert.ok(hostFile, 'no test file references enabledCount');
const probeRoot = copyTree(join(root, '.oracle-probe'));
const probeTests =
  readFileSync(join(probeRoot, 'tests', hostFile), 'utf8') +
  "\n\nimport { test as zzTest } from 'node:test';\nimport zzAssert from 'node:assert/strict';\nimport { enable as zzEnable, isEnabled as zzIsEnabled, enabledCount as zzEnabledCount } from '../src/flags.js';\n\nzzTest('zz probe enables a flag of its own', () => {\n  zzEnable('zz-probe-flag');\n  zzAssert.equal(zzIsEnabled('zz-probe-flag'), true);\n});\n\nzzTest('zz probe still gets a pristine session', () => {\n  zzAssert.equal(zzEnabledCount(), 0);\n});\n";
writeFileSync(join(probeRoot, 'tests', hostFile), probeTests);
assert.equal(
  runSuite(probeRoot),
  0,
  'a test appended after the suite must still see a pristine session - cleanup has to cover every test, not only the seeded order',
);
console.log('DEFLAKE_ORACLE order robust');

// 5) Mutant: restore the ORIGINAL leaking test file - the suite must fail
// again, proving the seeded defect is still detectable and the green suite
// comes from removed nondeterminism, not from a neutered module or dodge.
const ORIGINAL_TEST_FILE = `import assert from 'node:assert/strict';
import { test } from 'node:test';
import { enable, disable, isEnabled, enabledCount } from '../src/flags.js';

test('enable turns a flag on', () => {
  enable('beta-banner');
  assert.equal(isEnabled('beta-banner'), true);
});

test('disable turns a flag off again', () => {
  enable('holiday-theme');
  disable('holiday-theme');
  assert.equal(isEnabled('holiday-theme'), false);
});

test('unknown flags read as disabled', () => {
  assert.equal(isEnabled('dark-mode'), false);
});

test('a fresh session starts with no flags enabled', () => {
  assert.equal(enabledCount(), 0);
});
`;
const mutantRoot = copyTree(join(root, '.oracle-mutant'));
writeFileSync(join(mutantRoot, 'tests', 'flags.test.mjs'), ORIGINAL_TEST_FILE);
assert.notEqual(
  runSuite(mutantRoot),
  0,
  'restoring the original leaking order must make the suite fail again - the seeded defect stopped being detectable',
);
console.log('DEFLAKE_ORACLE mutant caught');
console.log('DEFLAKE_ORACLE done');
